import java.io.*;
import java.util.*;

public class Main {
    static int[] parent;
    static int[] size;

    static int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static void union(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (size[a] < size[b]) {
            int t = a;
            a = b;
            b = t;
        }
        parent[b] = a;
        size[a] += size[b];
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int M = fs.nextInt();

        parent = new int[N + 1];
        size = new int[N + 1];

        for (int i = 1; i <= N; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        int[] eu = new int[M];
        int[] ev = new int[M];

        int[] head = new int[N + 1];
        Arrays.fill(head, -1);

        int[] to = new int[2 * M];
        int[] nxt = new int[2 * M];
        int[] deg = new int[N + 1];

        int idx = 0;

        for (int i = 0; i < M; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();

            eu[i] = u;
            ev[i] = v;

            union(u, v);

            to[idx] = v;
            nxt[idx] = head[u];
            head[u] = idx++;
            deg[u]++;

            to[idx] = u;
            nxt[idx] = head[v];
            head[v] = idx++;
            deg[v]++;
        }

        long[] edgeCount = new long[N + 1];

        for (int i = 0; i < M; i++) {
            int r = find(eu[i]);
            edgeCount[r]++;
        }

        int candidateRoot = -1;

        for (int v = 1; v <= N; v++) {
            if (find(v) == v) {
                long s = size[v];
                long maxEdges = s * (s - 1) / 2;
                if (edgeCount[v] < maxEdges) {
                    candidateRoot = v;
                    break;
                }
            }
        }

        if (candidateRoot == -1) {
            System.out.println("-1");
            return;
        }

        int root = candidateRoot;
        int rootSize = size[root];

        int u = -1;
        for (int v = 1; v <= N; v++) {
            if (find(v) == root && deg[v] < rootSize - 1) {
                u = v;
                break;
            }
        }

        if (u == -1) {
            System.out.println("-1");
            return;
        }

        boolean[] isNeighbor = new boolean[N + 1];

        for (int e = head[u]; e != -1; e = nxt[e]) {
            isNeighbor[to[e]] = true;
        }

        for (int v = 1; v <= N; v++) {
            if (v != u && find(v) == root && !isNeighbor[v]) {
                System.out.println(u + " " + v);
                return;
            }
        }

        System.out.println("-1");
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
